//! Two-threaded zc-ring-x1 spsc v0 round-trip bench, closure
//! (`reserve_slot_with`) API, spin waits, the index-line ring.

use std::hint::black_box;
use std::thread;

use zc_ring_x1::{Consumer, Producer};

