fn resolve_target(path: &Path) -> Target {
    let shaped_dir = path.as_os_str().to_string_lossy().ends_with('/');
    if shaped_dir || path.is_dir() {
        Target::Dir(path.to_path_buf())
    } else {
        Target::File(path.to_path_buf())
    }
